package com.acme.imageprocessor.controller;

import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.http.ResponseEntity;
import java.io.*;
import java.nio.file.*;

@RestController
@RequestMapping("/api/v1/images")
public class ImageProcessorController {

    private static final String UPLOAD_DIR = "/data/uploads/";
    private static final String CONVERT_BIN = "/usr/local/bin/imgconvert";
    private static final int MAX_DIMENSION_PARAM_LENGTH = 32;

    @PostMapping("/resize")
    public ResponseEntity<byte[]> resizeImage(
            @RequestParam("file") MultipartFile file,
            @RequestParam("width") String width,
            @RequestParam("height") String height,
            @RequestParam(value = "format", defaultValue = "png") String format) throws Exception {

        // Save uploaded file
        String filename = System.currentTimeMillis() + "_" + file.getOriginalFilename();
        Path inputPath = Paths.get(UPLOAD_DIR, filename);
        Files.createDirectories(inputPath.getParent());
        Files.write(inputPath, file.getBytes());

        String outputFilename = filename.replaceAll("\\.[^.]+$", "." + format);
        Path outputPath = Paths.get(UPLOAD_DIR, "out_" + outputFilename);

        // Build command - dimensions are passed directly to native binary
        // imgconvert uses a fixed-size stack buffer (256 bytes) for parsing dimensions
        String[] command = {
            CONVERT_BIN,
            "--input", inputPath.toString(),
            "--output", outputPath.toString(),
            "--width", width,
            "--height", height,
            "--format", format
        };

        ProcessBuilder pb = new ProcessBuilder(command);
        pb.redirectErrorStream(true);
        Process process = pb.start();

        // Read process output
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        StringBuilder output = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            output.append(line).append("\n");
        }

        int exitCode = process.waitFor();

        if (exitCode != 0) {
            Files.deleteIfExists(inputPath);
            return ResponseEntity.status(500)
                .body(("Conversion failed: " + output.toString()).getBytes());
        }

        byte[] result = Files.readAllBytes(outputPath);

        // Cleanup
        Files.deleteIfExists(inputPath);
        Files.deleteIfExists(outputPath);

        return ResponseEntity.ok()
            .header("Content-Type", "image/" + format)
            .body(result);
    }

    @PostMapping("/metadata")
    public ResponseEntity<String> extractMetadata(
            @RequestParam("file") MultipartFile file,
            @RequestParam(value = "fields", defaultValue = "all") String fields) throws Exception {

        String filename = System.currentTimeMillis() + "_" + file.getOriginalFilename();
        Path inputPath = Paths.get(UPLOAD_DIR, filename);
        Files.write(inputPath, file.getBytes());

        // fields parameter also passed to native binary with fixed buffer
        String[] command = {
            CONVERT_BIN,
            "--metadata",
            "--input", inputPath.toString(),
            "--fields", fields
        };

        ProcessBuilder pb = new ProcessBuilder(command);
        pb.redirectErrorStream(true);
        Process process = pb.start();

        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        StringBuilder output = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            output.append(line).append("\n");
        }

        process.waitFor();
        Files.deleteIfExists(inputPath);

        return ResponseEntity.ok(output.toString());
    }
}
